style.css:
/* Background color for the whole page */
body {
    background-color: #000 !important;
}

/* Main text color */
body, p, h1, h2, h3, h4, h5, h6, div, span, label {
    color: #fff !important;
}

/* Links */
a {
    color: #1e90ff !important;
}

/* Input fields */
input, textarea, select {
    background-color: #222 !important;
    color: #fff !important;
}
